/**
 * An app-style tab bar for a phone: an icon over a label per tab, the current one marked. Axes: labels (show,
 * hide: icons only with the name hidden), position (static, sticky: stays at the bottom of the page), tone.
 */
import { type ReactNode } from "react";
import { Block } from "../primitives/block/block";
import { Inline } from "../primitives/inline/inline";
import { Link } from "../primitives/link/link";
import { List } from "../primitives/list/list";
import { ListItem } from "../primitives/list/list-item";
import { LucideIcon } from "../primitives/lucide-icon/lucide-icon";
import { cn } from "../utils";
import type { NavLink } from "./nav-bar.types";

export type BottomNavProps = {
  label: string;
  tabs: NavLink[];
  current?: string;
  labels?: "show" | "hide";
  position?: "static" | "sticky";
  tone?: "default" | "muted";
};

export function BottomNav({
  label,
  tabs,
  current = "",
  labels = "show",
  position = "static",
  tone = "default",
}: BottomNavProps) {
  return (
    <Block
      tag="nav"
      className={cn(
        "mx-auto w-full max-w-md border-t border-border",
        (((tone as string) === "muted") ? "bg-muted" : "bg-background"),
        (((position as string) === "sticky") ? "sticky bottom-0 z-40" : "")
      )}
      aria-label={label}
      data-testid="bottom-nav"
      data-position={position}
    >
      <List className="m-0 grid list-none grid-flow-col auto-cols-fr p-0" data-testid="items">
        {(tabs ?? []).map((tab) => (
          <ListItem key={tab.id}>
            <Link
              href="#/"
              variant="default"
              aria-current={((tab.id === current) ? "page" : undefined)}
              className={cn(
                "flex flex-col items-center gap-2 py-2 text-xs",
                ((tab.id === current) ? "font-semibold text-primary" : "text-muted-foreground")
              )}
              data-testid="item"
            >
              <LucideIcon name={tab.icon} size={20} />
              <Inline className={(((labels as string) === "hide") ? "sr-only" : "")}>
                {tab.name}
              </Inline>
            </Link>
          </ListItem>
        ))}
      </List>
    </Block>
  );
}
